COMMIT;

SELECT c.course_code, t.team_no, t.name AS team_name, p.name AS project_name,
       (SELECT COUNT(*) FROM team_member tm WHERE tm.team_id = t.id) AS members,
       (SELECT COUNT(*) FROM sprint s JOIN jira_integration j ON j.id = s.jira_integration_id WHERE j.project_id = p.id) AS sprints,
       (SELECT COUNT(*) FROM task tk WHERE tk.project_id = p.id) AS tasks
FROM course c
JOIN team t ON t.course_id = c.id
LEFT JOIN project p ON p.id = t.project_id
WHERE c.id IN ('aa110000-0000-4000-8000-00000000003f', 'aa110000-0000-4000-8000-000000000040')
ORDER BY c.course_code, t.team_no;
