INSERT INTO project (id, course_id, project_type_id, name, description, created_by_user_id) VALUES
    ('aa110000-0000-4000-8000-000000000083', 'aa110000-0000-4000-8000-00000000003f', '11111111-1111-1111-1111-111111111111', 'Hệ thống quản lý thư viện số', 'Danh mục sách, mượn trả, đặt chỗ, tìm kiếm và phiếu phạt cho thư viện trường.', 'aa110000-0000-4000-8000-000000000001'),
    ('aa110000-0000-4000-8000-0000000000a3', 'aa110000-0000-4000-8000-00000000003f', '11111111-1111-1111-1111-111111111111', 'Nền tảng thương mại điện tử', 'Gian hàng, giỏ hàng, thanh toán, đơn hàng và theo dõi vận chuyển.', 'aa110000-0000-4000-8000-00000000000b'),
    ('aa110000-0000-4000-8000-0000000000c1', 'aa110000-0000-4000-8000-00000000003f', '11111111-1111-1111-1111-111111111111', 'Ứng dụng đặt lịch khám bệnh', 'Lịch bác sĩ, đặt khám, hồ sơ bệnh nhân, nhắc lịch và nhận xét sau buổi khám.', 'aa110000-0000-4000-8000-000000000015'),
    ('aa110000-0000-4000-8000-0000000000df', 'aa110000-0000-4000-8000-000000000040', '11111111-1111-1111-1111-111111111111', 'Hệ thống quản lý ký túc xá', 'Phòng ở, đăng ký chỗ, hóa đơn điện nước, sự cố phòng và nội quy.', 'aa110000-0000-4000-8000-00000000001f'),
    ('aa110000-0000-4000-8000-0000000000fd', 'aa110000-0000-4000-8000-000000000040', '11111111-1111-1111-1111-111111111111', 'Cổng việc làm cho sinh viên', 'Tin tuyển dụng, hồ sơ ứng viên, nộp đơn, lịch phỏng vấn và theo dõi kết quả.', 'aa110000-0000-4000-8000-000000000031'),
    ('aa110000-0000-4000-8000-00000000011a', 'aa110000-0000-4000-8000-000000000040', '11111111-1111-1111-1111-111111111111', 'Cổng đăng ký sự kiện', 'Sự kiện câu lạc bộ, phiếu đăng ký, nhắc đóng phí và danh sách người tham dự.', 'aa110000-0000-4000-8000-000000000029');
